"use client";

import React, { useMemo, useState } from "react";
import { useParams, useRouter } from "next/navigation";

import { useAuth } from "@/ui/auth/useAuth";
import { useItemDetailSWR } from "@/services/useItemDetailSWR";
import { useUserProfileSWR } from "@/services/useUserProfileSWR";

import { getImageUrl } from "@/utils/utils";
import styles from "./PurchasePage.module.css";

export default function PurchasePage() {
  const router = useRouter();
  const params = useParams();
  const { user, isAuthenticated, apiClient } = useAuth();

  /* =========================
     itemId 解決
  ========================= */
  const itemId = useMemo(() => {
    const raw = params.itemId;
    const id = Array.isArray(raw) ? raw[0] : raw;
    const n = Number(id);
    return Number.isNaN(n) ? null : n;
  }, [params.itemId]);

  /* =========================
     Query
  ========================= */
  const { item, isLoading: isItemLoading, isError } = useItemDetailSWR(itemId);

  const { profile, isLoading: isProfileLoading } = useUserProfileSWR(user?.id);

  /* =========================
     Local State
  ========================= */
  const [paymentMethod, setPaymentMethod] = useState<
    "convenience" | "card" | ""
  >("");

  const isLoading = isItemLoading || isProfileLoading;

  /* =========================
     Guard
  ========================= */
  if (!isAuthenticated) {
    router.push("/login");
    return null;
  }

  if (isLoading) {
    return <p className={styles.loading}>購入情報を読み込み中...</p>;
  }

  if (isError || !item) {
    return <p className={styles.error}>商品が見つかりませんでした。</p>;
  }

  /* =========================
     Purchase Command
  ========================= */
  const submitPurchase = async () => {
    if (!apiClient || !paymentMethod) return;

    try {
      const res = await apiClient.post("/purchase", {
        item_id: item.id,
        payment_method: paymentMethod,
      });

      if (paymentMethod === "card" && res.data?.stripe_url) {
        window.location.href = res.data.stripe_url;
        return;
      }

      router.push("/thanks");
    } catch {
      alert("購入処理に失敗しました");
    }
  };

  /* =========================
     JSX
  ========================= */
  return (
    <div className={styles.wrapper}>
      <h1 className={styles.title}>購入内容の確認</h1>

      {/* 商品 */}
      <div className={styles.itemBox}>
        <img
          src={getImageUrl(item.item_image)}
          alt={item.name}
          className={styles.itemImage}
        />
        <div>
          <p className={styles.itemName}>{item.name}</p>
          <p className={styles.itemPrice}>¥{item.price.toLocaleString()}</p>
        </div>
      </div>

      {/* 配送先 */}
      <div className={styles.section}>
        <h2>配送先</h2>

        {profile ? (
          <>
            <p>〒{profile.postNumber}</p>
            <p>{profile.address}</p>
            {profile.building && <p>{profile.building}</p>}
          </>
        ) : (
          <p className={styles.warn}>
            配送先住所が未登録です。
            <button onClick={() => router.push("/mypage/profile")}>
              登録する
            </button>
          </p>
        )}
      </div>

      {/* 支払い方法 */}
      <div className={styles.section}>
        <h2>支払い方法</h2>

        <select
          value={paymentMethod}
          onChange={(e) =>
            setPaymentMethod(e.target.value as "convenience" | "card")
          }
        >
          <option value="">選択してください</option>
          <option value="convenience">コンビニ払い</option>
          <option value="card">カード払い</option>
        </select>
      </div>

      {/* 実行 */}
      <button
        className={styles.purchaseButton}
        disabled={!paymentMethod || !profile}
        onClick={submitPurchase}
      >
        購入する
      </button>
    </div>
  );
}
