import useSWR from "swr";
import type { AxiosInstance } from "axios";
import { useAuth } from "@/ui/auth/useAuth";
import type { UserProfile } from "@/domain/user/UserProfile";

type UserProfileResponse = {
  profile: {
    post_number: string;
    address: string;
    building?: string | null;
  };
};

export const useUserProfileSWR = (userId?: number) => {
  const { apiClient, isAuthenticated } = useAuth() as {
    apiClient: AxiosInstance | null;
    isAuthenticated: boolean;
  };

  const shouldFetch = isAuthenticated && !!userId && !!apiClient;

  const fetcher = async (): Promise<UserProfile | null> => {
    if (!apiClient) return null;

    const res = await apiClient.get<UserProfileResponse>("/mypage/profile");

    return {
      userId,
      postNumber: res.data.profile.post_number,
      address: res.data.profile.address,
      building: res.data.profile.building ?? undefined,
    };
  };

  const { data, error, isLoading } = useSWR<UserProfile | null>(
    shouldFetch ? ["user-profile", userId] : null,
    fetcher,
  );

  return {
    profile: data,
    isLoading,
    error,
  };
};
